import { Component, OnInit } from '@angular/core';
import { ApiService } from '../services/api.service';
import { Student } from '../models/models';

@Component({
  selector: 'app-students',
  templateUrl: './students.component.html',
})
export class StudentsComponent implements OnInit {
  students: Student[] = [];
  loading = true;
  error = '';
  showForm = false;
  editing: Student | null = null;
  form = { name: '', email: '' };
  submitting = false;

  constructor(private api: ApiService) {}

  ngOnInit(): void { this.load(); }

  load(): void {
    this.loading = true;
    this.api.getStudents().subscribe({
      next: (data) => { this.students = data; this.loading = false; },
      error: () => { this.error = 'Failed to load students.'; this.loading = false; },
    });
  }

  openAdd(): void {
    this.editing = null;
    this.form = { name: '', email: '' };
    this.error = '';
    this.showForm = true;
  }

  openEdit(s: Student): void {
    this.editing = s;
    this.form = { name: s.name, email: s.email };
    this.error = '';
    this.showForm = true;
  }

  cancel(): void {
    this.showForm = false;
    this.editing = null;
    this.error = '';
  }

  submit(): void {
    this.submitting = true;
    this.error = '';
    const req = this.editing
      ? this.api.updateStudent(this.editing.id, this.form)
      : this.api.createStudent(this.form);

    req.subscribe({
      next: () => { this.cancel(); this.load(); this.submitting = false; },
      error: (err) => {
        const msg = err.error?.message;
        this.error = Array.isArray(msg) ? msg.join(', ') : (msg || 'An error occurred.');
        this.submitting = false;
      },
    });
  }

  deleteStudent(s: Student): void {
    if (!confirm(`Delete student "${s.name}"?\nThis will also delete their profile and remove all enrollments.`)) return;
    this.api.deleteStudent(s.id).subscribe({
      next: () => this.load(),
      error: () => { this.error = 'Failed to delete student.'; },
    });
  }
}
<div class="container">
  <div class="page-header">
    <h2>Students</h2>
    <button class="btn btn-primary" (click)="openAdd()">+ Add Student</button>
  </div>

  <div *ngIf="error && !showForm" class="alert-error">{{ error }}</div>

  <div *ngIf="showForm" class="card form-card">
    <h3>{{ editing ? 'Edit Student' : 'New Student' }}</h3>
    <div *ngIf="error" class="alert-error">{{ error }}</div>
    <form (ngSubmit)="submit()" #f="ngForm">
      <div class="form-row">
        <div class="form-group">
          <label>Name</label>
          <input required name="name" [(ngModel)]="form.name" placeholder="Full name" />
        </div>
        <div class="form-group">
          <label>Email</label>
          <input required type="email" name="email" [(ngModel)]="form.email" placeholder="email@example.com" />
        </div>
      </div>
      <div class="form-actions">
        <button type="submit" class="btn btn-primary" [disabled]="submitting || f.invalid">
          {{ submitting ? 'Saving…' : (editing ? 'Save Changes' : 'Create Student') }}
        </button>
        <button type="button" class="btn btn-secondary" (click)="cancel()">Cancel</button>
      </div>
    </form>
  </div>

  <div *ngIf="loading" class="loading">Loading students…</div>

  <div *ngIf="!loading" class="card">
    <div *ngIf="students.length === 0" class="empty-state">
      No students yet. Click "+ Add Student" to get started.
    </div>
    <table *ngIf="students.length > 0">
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
          <th>Profile</th>
          <th>Courses Enrolled</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let s of students">
          <td>
            <a [routerLink]="['/students', s.id]" class="table-link">{{ s.name }}</a>
          </td>
          <td class="text-muted">{{ s.email }}</td>
          <td>
            <span *ngIf="s.profile" class="badge badge-green">Has Profile</span>
            <span *ngIf="!s.profile" class="badge badge-gray">No Profile</span>
          </td>
          <td>
            <span class="badge badge-blue">
              {{ s.courses?.length ?? 0 }} course{{ (s.courses?.length ?? 0) !== 1 ? 's' : '' }}
            </span>
          </td>
          <td>
            <div class="actions">
              <a [routerLink]="['/students', s.id]" class="btn btn-secondary btn-sm">View</a>
              <button class="btn btn-secondary btn-sm" (click)="openEdit(s)">Edit</button>
              <button class="btn btn-danger btn-sm" (click)="deleteStudent(s)">Delete</button>
            </div>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</div>
